+			let start = 0;
+			let end = sections.length;
+			while (start < end) {
+				const index = Math.floor((start + end) / 2);
+				if (sections[index].target.getBoundingClientRect().top > headingActivationOffset) {
+					end = index;
+				} else {
+					start = index + 1;
+				}
+			}
+			next = sections[start - 1]?.link;
